import os
import sqlite3
from flask import Flask, request, g, jsonify

app = Flask(__name__)
app.secret_key = os.environ.get('APP_SECRET', 'dev-secret-key')

DATABASE = 'db.sqlite3'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_db(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    conn = sqlite3.connect(DATABASE)
    try:
        conn.execute('''
            CREATE TABLE IF NOT EXISTS messages (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT NOT NULL,
                content TEXT NOT NULL,
                timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
            )
        ''')
        conn.commit()
    finally:
        conn.close()

@app.route('/messages', methods=['GET'])
def get_messages():
    try:
        limit = int(request.args.get('limit', 10))
        offset = int(request.args.get('offset', 0))
        sort = request.args.get('sort', 'desc').upper()
        if sort not in ('ASC', 'DESC'):
            sort = 'DESC'
    except ValueError:
        return jsonify({'error': 'Invalid limit or offset'}), 400

    if limit < 0 or offset < 0:
        return jsonify({'error': 'Limit and offset must be non-negative'}), 400

    db = get_db()
    query = f'''
        SELECT username, content, timestamp 
        FROM messages 
        ORDER BY timestamp {sort}
        LIMIT ? OFFSET ?
    '''
    cursor = db.execute(query, (limit, offset))
    rows = cursor.fetchall()
    cursor.close()

    messages = [{
        'username': row['username'],
        'content': row['content'],
        'timestamp': row['timestamp']
    } for row in rows]

    return jsonify(messages), 200

@app.route('/messages', methods=['POST'])
def post_message():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({'error': 'Invalid JSON body'}), 400

    username = data.get('username')
    content = data.get('content')

    if not isinstance(username, str) or not username.strip():
        return jsonify({'error': 'Username is required and must be non-empty'}), 400
    if not isinstance(content, str) or not content.strip():
        return jsonify({'error': 'Content is required and must be non-empty'}), 400

    db = get_db()
    try:
        db.execute(
            'INSERT INTO messages (username, content) VALUES (?, ?)',
            (username, content)
        )
        db.commit()
    except sqlite3.Error:
        return jsonify({'error': 'Database error'}), 400

    return jsonify({'status': 'ok'}), 200

init_db()

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
